import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>تحويل PNG إلى JPG مشهور بتصغير الملفات، لكن التوفير ليس نفسه لكل صورة. بعض الصور تصغر إلى عُشر حجمها، وبعضها لا يصغر أبدًا.</p>\n<p>فهم ما يدفع التوفير يساعدك على توقع النتيجة قبل التحويل، واختيار إعداد الجودة الصحيح.</p>\n<p>ينظر هذا المقال إلى الأرقام بصدق، حسب نوع الصورة، ويشرح المقايضات. وللتحويل الفعلي، استخدم <a href=\"/ar/tahwil-png-ila-jpg/\">محول PNG إلى JPG</a>.</p>\n<h2 id=\"why-png-is-big\">لماذا ملفات PNG كبيرة جدًا؟</h2>\n<p>لماذا ملفات PNG كبيرة جدًا؟ لأن PNG ضغط دون فقدان يحفظ كل بكسل بدقة. لقطة شاشة فيها نصوص وألوان كثيرة تزن ميغابايتات.</p>\n<p>PNG لا يتجاهل أي بيانات. كل بكسل يُحفظ كاملًا، وهذا يجعل الملفات كبيرة خاصة للصور المعقدة.</p>\n<h2 id=\"why-jpg-is-small\">لماذا ملفات JPG أصغر بكثير؟</h2>\n<p>لماذا ملفات JPG أصغر بكثير؟ لأن JPG ضغط مع فقدان يتجاهل التفاصيل الدقيقة التي لا تلاحظها العين. التدرجات والظلال تُبسط، فيصغر الملف.</p>\n<p>JPG يحفظ ما تراه عينك ويتجاهل الباقي. هذا هو سر صغر حجمه، وثمنه فقدان بسيط في الجودة.</p>\n<h2 id=\"savings-by-image-type\">التوفير حسب نوع الصورة</h2>\n<p>التوفير حسب نوع الصورة: الصور الفوتوغرافية توفر أكثر، واللقطات توفر كثيرًا، والرسوم البسيطة توفر أقل. كل نوع يتصرف بشكل مختلف.</p>\n<p>لقطة PNG بحجم 2 ميغابايت قد تصبح JPG بحجم 200 كيلوبايت. أيقونة صغيرة قد لا توفر شيئًا أبدًا.</p>\n<h2 id=\"quality-slider-maths\">منزلق الجودة بلغة عملية</h2>\n<p>منزلق الجودة بلغة عملية: جودة 95 تحافظ على كل شيء تقريبًا، و90 توازن ممتاز، و85 جيدة لمعظم الاستخدامات، و70 للمعاينات فقط.</p>\n<p>كل 10 نقاط جودة تخفض الحجم بشكل ملحوظ. جودة 80 أصغر بكثير من 90، لكن الفرق في الجودة قد يكون مرئيًا.</p>\n<h2 id=\"text-at-each-quality\">حدة النص في كل مستوى جودة</h2>\n<p>حدة النص في كل مستوى جودة: عند جودة 90 فأعلى، النص حاد وواضح. عند 85، النص مقروء لكن أقل حدة. عند 70، النص يضبب بوضوح.</p>\n<p>للقطات فيها نصوص، لا تنزل عن 85 أبدًا. النص الضبابي يجعل اللقطة عديمة الفائدة.</p>\n<h2 id=\"photos-at-each-quality\">الصور الفوتوغرافية في كل مستوى جودة</h2>\n<p>الصور الفوتوغرافية في كل مستوى جودة: عند 90، الصور تبدو مطابقة للأصل. عند 85، الفرق طفيف. عند 70، تظهر التشوهات في التدرجات.</p>\n<p>للصور المهمة، استخدم 90. للمشاركة اليومية، 85 كافية. لا تنزل عن 70 إلا للمعاينات الصغيرة.</p>\n<h2 id=\"when-savings-disappear\">متى يختفي التوفير؟</h2>\n<p>متى يختفي التوفير؟ عندما تكون الصورة بسيطة بألوان قليلة، مثل أيقونة أو رسم بسيط. PNG يضغطها جيدًا أصلًا، وJPG قد يكون أكبر.</p>\n<p>في هذه الحالة، لا تحوّل. احتفظ بـPNG للرسوم البسيطة، وحوّل فقط الصور المعقدة واللقطات.</p>\n<h2 id=\"choosing-the-right-setting\">كيف تختار الإعداد الصحيح لعملك؟</h2>\n<p>كيف تختار الإعداد الصحيح لعملك؟ فكر في الوجهة: للويب استخدم 85، وللطباعة استخدم 95، وللقطات النصية استخدم 90.</p>\n<p>جرّب إعدادات مختلفة على عينة صغيرة قبل تحويل دفعة كاملة. العينة تخبرك بالإعداد المثالي لعملك.</p>\n<h2 id=\"comparing-before-after\">كيف تقارن قبل وبعد بشكل صحيح؟</h2>\n<p>كيف تقارن قبل وبعد بشكل صحيح؟ افتح الصورتين جنبًا إلى جنب وكبّرهما. افحص النص والتدرجات والحواف في كلتيهما.</p>\n<p>لا تقارن من الذاكرة. المقارنة المباشرة تكشف الفروق الدقيقة التي تفوتك عند النظر إلى صورة واحدة.</p>\n<h2 id=\"batch-savings\">توفير الدفعات يتراكم بسرعة</h2>\n<p>توفير الدفعات يتراكم بسرعة: دفعة من 100 لقطة قد توفر مئات الميغابايت. التوفير الصغير لكل صورة يصبح كبيرًا عند العدد الكبير.</p>\n<p>لمجلد لقطات كامل، التحويل الجماعي قد يحرر مساحة تخزين كبيرة على جهازك أو في السحابة.</p>\n<h2 id=\"when-not-to-convert\">متى لا تحوّل أبدًا؟</h2>\n<p>متى لا تحوّل أبدًا؟ عندما تحتاج إلى شفافية، أو تحرير متكرر، أو أرشفة دون فقدان. في هذه الحالات، PNG هو الخيار الصحيح.</p>\n<p>لا تحوّل الشعارات الشفافة أو النسخ الرئيسية. التحويل يفقد معلومات لا يمكن استعادتها.</p>\n<h2 id=\"webp-alternative\">بديل WebP الذي يستحق المعرفة</h2>\n<p>بديل WebP الذي يستحق المعرفة: WebP أصغر من JPG بالجودة نفسها، ويدعم الشفافية أيضًا. للمواقع الحديثة، WebP هو الخيار الأفضل.</p>\n<p>حوّل إلى WebP باستخدام <a href=\"/ar/tahwil-png-ila-webp/\">محول PNG إلى WebP</a>. WebP يجمع بين صغر حجم JPG وشفافية PNG.</p>\n<h2 id=\"email-attachment-limits\">حدود مرفقات البريد الإلكتروني</h2>\n<p>حدود مرفقات البريد الإلكتروني: معظم خدمات البريد تحد المرفقات بـ25 ميغابايت. تحويل PNG إلى JPG يساعدك على البقاء ضمن الحد.</p>\n<p>إذا كان المرفق ما زال كبيرًا، فاضغط JPG أكثر أو قسّم الصور على عدة رسائل.</p>\n<h2 id=\"website-loading-speed\">سرعة تحميل الموقع الإلكتروني</h2>\n<p>سرعة تحميل الموقع الإلكتروني: الصور الكبيرة تبطئ موقعك. تحويل PNG إلى JPG يختصر وقت التحميل ويحسّن تجربة الزائر.</p>\n<p>كل 100 كيلوبايت توفرها من صورة تحسّن سرعة الصفحة. للمواقع، الحجم الصغير مهم جدًا.</p>\n<h2 id=\"storage-on-phone\">التخزين على هاتف ممتلئ</h2>\n<p>التخزين على هاتف ممتلئ: تحويل صور PNG إلى JPG يحرر مساحة كبيرة على هاتفك. الملفات الأصغر تعني مساحة أكبر للصور الجديدة.</p>\n<p>راجع مجلد لقطاتك أولًا. اللقطات القديمة هي أكبر مستهلك للمساحة في معظم الهواتف.</p>\n<h2 id=\"upload-limits-forms\">حدود الرفع في النماذج</h2>\n<p>حدود الرفع في النماذج: كثير من النماذج تحد حجم الملف المرفوع بـ5 أو 10 ميغابايت. تحويل PNG إلى JPG يساعدك على البقاء ضمن الحد.</p>\n<p>تحقق من حد الرفع قبل التحويل. إذا كان الحد صغيرًا، فقد تحتاج إلى جودة أقل أو أبعاد أصغر.</p>\n<h2 id=\"balancing-quality-batch\">كيف توازن الجودة في دفعة؟</h2>\n<p>كيف توازن الجودة في دفعة؟ استخدم إعدادًا واحدًا متوازنًا لكل الدفعة، مثل جودة 85. الاتساق أهم من الكمال لكل صورة.</p>\n<p>إذا كانت بعض الصور تحتاج إلى جودة أعلى، فحوّلها منفصلة. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-png-ila-jpg/\">الدليل الكامل لتحويل PNG إلى JPG</a> و<a href=\"/ar/blog/kayfiyya-tahwil-png-ila-jpg/\">كيفية تحويل PNG إلى JPG</a>، أو ابدأ من <a href=\"/ar/\">الصفحة الرئيسية</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما إعداد الجودة الذي يعطي أفضل توازن بين الحجم والجودة للقطات؟","answer":"جودة 90 هي أفضل توازن للقطات: النص يبقى حادًا والملف أصغر بكثير. للقطات النصية لا تنزل عن 85."},{"question":"لماذا كبر أيقوني الصغير بعد التحويل إلى JPG؟","answer":"لأن PNG يضغط الأيقونات الصغيرة البسيطة جيدًا أصلًا، بينما JPG يضيف بيانات ضغط معقدة. الأيقونات الصغيرة لا تستفيد من التحويل."},{"question":"هل جودة 90 بالمئة أفضل بشكل ملحوظ من 80 بالمئة للصور؟","answer":"الفرق واضح في الصور التفصيلية: جودة 90 تحافظ على تفاصيل أكثر، خاصة في التدرجات والظلال. للصور المهمة استخدم 90."},{"question":"كم يمكنني تصغير مجلد لقطات PNG بالجملة؟","answer":"تعتمد على عدد اللقطات وحجمها، لكن التوفير كبير عادة: مجلد لقطات بحجم 500 ميغابايت قد يصبح 50 ميغابايت بعد التحويل."},{"question":"هل يفيد خفض الجودة عن 70 بالمئة أحيانًا؟","answer":"نادرًا، لكن نعم: للصور المصغرة أو المعاينات الصغيرة التي لا تحتاج إلى جودة، جودة 70 كافية وتوفر مساحة إضافية."},{"question":"هل أحوّل PNG إلى JPG أم إلى WebP لموقعي الإلكتروني؟","answer":"لموقعك الإلكتروني، حوّل إلى WebP بدل JPG. WebP أصغر من JPG بالجودة نفسها، ويدعم الشفافية أيضًا."}];
